<script setup>
import { ref,watch,computed } from 'vue';import { useRoute } from 'vue-router';import { BedDouble,Users,Maximize,Check,ArrowLeft,ArrowUpRight } from 'lucide-vue-next';import { api,url } from '../lib/api';import { currency,today,nextDate } from '../lib/format';import StatePanel from '../components/StatePanel.vue';
const route=useRoute(),room=ref(null),error=ref(''),loading=ref(true),activeImage=ref(0);const images=computed(()=>room.value?.images?.length?room.value.images.map(i=>url(i.url)):['/room-1.jpg','/room-2.jpg']);async function load(){loading.value=true;error.value='';room.value=null;activeImage.value=0;try{room.value=(await api('/room-types/'+route.params.id)).data;}catch(e){error.value=e.message;}finally{loading.value=false;}}watch(()=>route.params.id,load,{immediate:true});
const query=computed(()=>({check_in:route.query.check_in||today(),check_out:route.query.check_out||nextDate(today()),adults:route.query.adults||2,children:route.query.children||0,room_type_id:route.params.id}));
</script>
<template><div class="container section compact"><RouterLink to="/rooms" class="text-link"><ArrowLeft :size="17"/> กลับไปห้องพัก</RouterLink><StatePanel :loading="loading" :error="error"/><template v-if="room"><div class="detail-title"><div><p class="eyebrow">ROOMS & SUITES</p><h1>{{ room.type_name }}</h1></div><div class="price-large">{{ currency(room.price_per_night) }}<small> / คืน</small></div></div><div class="gallery"><img :src="images[activeImage]" :alt="room.type_name"/><div class="gallery-thumbs"><button v-for="(image,index) in images" :key="image" @click="activeImage=index" :class="{active:index===activeImage}" :aria-label="'ดูภาพที่ '+(index+1)"><img :src="image" :alt="'ภาพที่ '+(index+1)"/></button></div><span v-if="!room.images.length" class="photo-caption">ภาพประกอบห้องพัก</span></div><div class="detail-grid"><div><h2>พื้นที่สำหรับการพักผ่อนของคุณ</h2><p class="body-copy">{{ room.description || 'ห้องพักที่พร้อมสำหรับการเดินทางครั้งต่อไป' }}</p><div class="spec-grid"><span><Users/> {{ room.adult_capacity }} ผู้ใหญ่ · {{ room.child_capacity }} เด็ก</span><span><BedDouble/> {{ room.bed_count }} เตียง · {{ room.bed_type }}</span><span v-if="room.room_size"><Maximize/> {{ Number(room.room_size) }} ตารางเมตร</span></div><h3>สิ่งอำนวยความสะดวก</h3><div class="amenity-grid"><span v-for="item in room.amenities" :key="item.amenity_id"><Check :size="17"/>{{ item.amenity_name }}</span></div><p v-if="!room.amenities.length" class="muted">โรงแรมยังไม่ได้ระบุสิ่งอำนวยความสะดวก</p></div><aside class="booking-aside panel"><p class="eyebrow">MAKE IT YOUR STAY</p><h3>ห้องนี้เหมาะกับคุณไหม?</h3><p class="muted">เลือกวันเข้าพักเพื่อตรวจสอบห้องว่างและราคาสำหรับการเดินทางของคุณ</p><RouterLink :to="{path:'/rooms',query}" class="btn primary full">ตรวจสอบห้องว่าง <ArrowUpRight :size="18"/></RouterLink><small>ราคาห้องคำนวณตามจำนวนคืน<br/>ตรวจสอบรายละเอียดก่อนยืนยันทุกครั้ง</small></aside></div></template></div></template>
